/**
 * External dependencies
 */
import { isEqual, keyBy, omit } from 'lodash';
import type { AnyAction } from '@nab/types';

/**
 * Internal dependencies
 */
import { INIT_STATE } from './config';
import type { Action } from './actions';
import type { State } from './types';

export function reducer( state = INIT_STATE, action: AnyAction ): State {
	return actualReducer( state, action as Action ) ?? state;
}

function actualReducer( state: State, action: Action ): State {
	switch ( action.type ) {
		case 'ADD_SEGMENTATION_RULE_TYPE_DEFINITIONS': {
			const newDefinitions = {
				...state.segmentationRuleTypeDefinitions,
				...keyBy( action.definitions, 'name' ),
			};
			if (
				isEqual( state.segmentationRuleTypeDefinitions, newDefinitions )
			) {
				return state;
			}

			return initializeSegmentationRuleTypes( {
				...state,
				segmentationRuleTypeDefinitions: newDefinitions,
			} );
		}

		case 'REMOVE_SEGMENTATION_RULE_TYPE_DEFINITIONS': {
			const newDefinitions = omit(
				state.segmentationRuleTypeDefinitions,
				action.names
			);
			if (
				isEqual( state.segmentationRuleTypeDefinitions, newDefinitions )
			) {
				return state;
			}
			return initializeSegmentationRuleTypes( {
				...state,
				segmentationRuleTypeDefinitions: newDefinitions,
			} );
		}

		case 'ADD_SEGMENTATION_RULE_TYPE_RUNTIMES': {
			const newRuntimes = action.runtimes.reduce(
				( runtimes, registration ) => ( {
					...runtimes,
					[ registration.name ]: registration.runtime,
				} ),
				state.segmentationRuleTypeRuntimes
			);
			if ( isEqual( state.segmentationRuleTypeRuntimes, newRuntimes ) ) {
				return state;
			}

			return initializeSegmentationRuleTypes( {
				...state,
				segmentationRuleTypeRuntimes: newRuntimes,
			} );
		}

		case 'REMOVE_SEGMENTATION_RULE_TYPE_RUNTIMES': {
			const newRuntimes = omit(
				state.segmentationRuleTypeRuntimes,
				action.names
			);
			if ( isEqual( state.segmentationRuleTypeRuntimes, newRuntimes ) ) {
				return state;
			}
			return initializeSegmentationRuleTypes( {
				...state,
				segmentationRuleTypeRuntimes: newRuntimes,
			} );
		}

		case 'ADD_SEGMENTATION_RULE_TYPE_CATEGORIES': {
			const newCategories = action.categories.filter(
				( category ) =>
					! isEqual( state.categories[ category.name ], category )
			);
			if ( ! newCategories.length ) {
				return state;
			}

			return {
				...state,
				categories: {
					...state.categories,
					...keyBy( newCategories, 'name' ),
				},
			};
		}

		case 'REMOVE_SEGMENTATION_RULE_TYPE_CATEGORIES': {
			const newCategories = omit( state.categories, action.names );
			if ( isEqual( state.categories, newCategories ) ) {
				return state;
			}
			return {
				...state,
				categories: newCategories,
			};
		}
	}
}

function initializeSegmentationRuleTypes( state: State ): State {
	const segmentationRuleTypes = Object.keys(
		state.segmentationRuleTypeDefinitions
	).reduce< State[ 'segmentationRuleTypes' ] >( ( types, name ) => {
		const runtime = state.segmentationRuleTypeRuntimes[ name ];
		if ( ! runtime ) {
			return types;
		}

		return {
			...types,
			[ name ]: {
				...state.segmentationRuleTypeDefinitions[ name ],
				...runtime,
			} as State[ 'segmentationRuleTypes' ][ string ],
		};
	}, {} );

	if ( isEqual( state.segmentationRuleTypes, segmentationRuleTypes ) ) {
		return state;
	}

	return {
		...state,
		segmentationRuleTypes,
	};
}
