/**
 * External dependencies
 */
import { castArray } from 'lodash';
import type {
	SegmentationRuleCategory,
	SegmentationRuleCategoryName,
	SegmentationRuleTypeDefinition,
	SegmentationRuleTypeName,
	SegmentationRuleTypeRuntime,
} from '@nab/types';

export type Action =
	| AddSegmentationRuleTypeDefinitions
	| RemoveSegmentationRuleTypeDefinitions
	| AddSegmentationRuleTypeRuntimes
	| RemoveSegmentationRuleTypeRuntimes
	| AddSegmentationRuleTypeCategories
	| RemoveSegmentationRuleTypeCategories;

export function addSegmentationRuleTypeDefinitions(
	definitions:
		| SegmentationRuleTypeDefinition
		| ReadonlyArray< SegmentationRuleTypeDefinition >
): AddSegmentationRuleTypeDefinitions {
	return {
		type: 'ADD_SEGMENTATION_RULE_TYPE_DEFINITIONS',
		definitions: castArray( definitions ),
	};
}

export function removeSegmentationRuleTypeDefinitions(
	names: SegmentationRuleTypeName | ReadonlyArray< SegmentationRuleTypeName >
): RemoveSegmentationRuleTypeDefinitions {
	return {
		type: 'REMOVE_SEGMENTATION_RULE_TYPE_DEFINITIONS',
		names: castArray( names ),
	};
}

export function addSegmentationRuleTypeRuntimes(
	runtimes:
		| SegmentationRuleTypeRuntimeRegistration
		| ReadonlyArray< SegmentationRuleTypeRuntimeRegistration >
): AddSegmentationRuleTypeRuntimes {
	return {
		type: 'ADD_SEGMENTATION_RULE_TYPE_RUNTIMES',
		runtimes: castArray( runtimes ),
	};
}

export function removeSegmentationRuleTypeRuntimes(
	names: SegmentationRuleTypeName | ReadonlyArray< SegmentationRuleTypeName >
): RemoveSegmentationRuleTypeRuntimes {
	return {
		type: 'REMOVE_SEGMENTATION_RULE_TYPE_RUNTIMES',
		names: castArray( names ),
	};
}

export function addSegmentationRuleTypeCategories(
	categories:
		SegmentationRuleCategory | ReadonlyArray< SegmentationRuleCategory >
): AddSegmentationRuleTypeCategories {
	return {
		type: 'ADD_SEGMENTATION_RULE_TYPE_CATEGORIES',
		categories: castArray( categories ),
	};
}

export function removeSegmentationRuleTypeCategories(
	names:
		| SegmentationRuleCategoryName
		| ReadonlyArray< SegmentationRuleCategoryName >
): RemoveSegmentationRuleTypeCategories {
	return {
		type: 'REMOVE_SEGMENTATION_RULE_TYPE_CATEGORIES',
		names: castArray( names ),
	};
}

// ============
// HELPER TYPES
// ============

type AddSegmentationRuleTypeDefinitions = {
	readonly type: 'ADD_SEGMENTATION_RULE_TYPE_DEFINITIONS';
	readonly definitions: ReadonlyArray< SegmentationRuleTypeDefinition >;
};

type RemoveSegmentationRuleTypeDefinitions = {
	readonly type: 'REMOVE_SEGMENTATION_RULE_TYPE_DEFINITIONS';
	readonly names: ReadonlyArray< SegmentationRuleTypeName >;
};

type AddSegmentationRuleTypeRuntimes = {
	readonly type: 'ADD_SEGMENTATION_RULE_TYPE_RUNTIMES';
	readonly runtimes: ReadonlyArray< SegmentationRuleTypeRuntimeRegistration >;
};

type RemoveSegmentationRuleTypeRuntimes = {
	readonly type: 'REMOVE_SEGMENTATION_RULE_TYPE_RUNTIMES';
	readonly names: ReadonlyArray< SegmentationRuleTypeName >;
};

type AddSegmentationRuleTypeCategories = {
	readonly type: 'ADD_SEGMENTATION_RULE_TYPE_CATEGORIES';
	readonly categories: ReadonlyArray< SegmentationRuleCategory >;
};

type RemoveSegmentationRuleTypeCategories = {
	readonly type: 'REMOVE_SEGMENTATION_RULE_TYPE_CATEGORIES';
	readonly names: ReadonlyArray< SegmentationRuleCategoryName >;
};

export type SegmentationRuleTypeRuntimeRegistration = {
	readonly name: SegmentationRuleTypeName;
	readonly runtime: SegmentationRuleTypeRuntime;
};
